// FILE: src/components/layout/Sidebar.tsx
"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

const nav = [
  { name: "Dashboard", href: "/(dashboard)/dashboard" },
  { name: "Leads", href: "/(dashboard)/leads" },
  { name: "Appointments", href: "/(dashboard)/appointments" },
  { name: "Messages", href: "/(dashboard)/messages" },
  { name: "Billing", href: "/(dashboard)/billing" },
  { name: "Settings", href: "/(dashboard)/settings" },
];

export default function Sidebar() {
  const pathname = usePathname();
  return (
    <aside className="w-60 bg-slate-950/40 border-r border-slate-800 p-4 flex flex-col gap-4">
      <div className="text-2xl font-bold">Sylor.ai</div>
      <nav className="flex flex-col gap-2">
        {nav.map((item) => {
          const active = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`rounded-lg px-3 py-2 text-sm ${
                active
                  ? "bg-brand-primary text-white"
                  : "text-dark-text-secondary hover:bg-slate-800/40"
              }`}
            >
              {item.name}
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}
